window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f303b83119d1a616"]={"versions": [{"id": "FIG-f303b83119d1a616", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Botschaftssequenzdiagramm (Timing Diagram) im Kontext des AUTOSAR Classic CAN Network Managements (<code>CanNm</code>). Das Diagramm illustriert das Verhalten von drei Netzwerkknoten (Knoten 1, 2, 3) bei Beendigung der Buslastreduktion und Reaktivierung der regulären NM-Botschaftsübertragung sowie das Zurücksetzen des NM-Timeout-Timers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Netzwerkknoten</strong>: Knoten 1 (grün), Knoten 2 (blau) und Knoten 3 (gelb), jeweils auf separaten horizontalen Zeitachsen dargestellt.\n</li><li><strong>Zustände / Modi</strong>:\n<ul class=\"fig-list\"><li><code>RM</code>: Repeat Message State\n</li><li><code>NO</code>: Normal Operation State\n</li><li><code>RS</code>: Ready Sleep State\n</li></ul>\n</li><li><strong>Schnittstellen / API-Aufrufe</strong>:\n<ul class=\"fig-list\"><li><code>Nm_StopBusLoadReduction()</code>\n</li><li><code>Nm_StartTransmission()</code>\n</li></ul>\n</li><li><strong>Ereignisse &amp; Timer-Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>Restart of the NM-Timeout Timer</code>\n</li><li>Auslöser <code>at NM-Msg Tx Conf</code>: Bestätigung einer gesendeten NM-PDU (gefüllter Kreis)\n</li><li>Auslöser <code>at NM-Msg Rx Ind</code>: Empfangsanzeige einer NM-PDU (ungefüllter Kreis)\n</li><li>NM-Sendeimpulse/Botschaften der Knoten auf dem Bus (farbige vertikale Balken 1, 2, 3) entlang der Zeitachse <code>time</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initial befinden sich alle drei Knoten im Zustand <code>RM</code> (Repeat Message).\n</li><li>Zu einem definierten Zeitpunkt wird für alle Knoten <code>(1,2,3)</code> der synchrone Ablauf getriggert: <code>Nm_StopBusLoadReduction()</code> gefolgt von <code>Nm_StartTransmission()</code>.\n</li><li>In der Folge senden die Knoten nacheinander zyklisch ihre NM-Botschaften (dargestellt durch die farbigen Balken 1, 2, 3 auf dem Bus).\n</li><li>Jeder Knoten empfängt die Botschaften der jeweils anderen Knoten (<code>NM-Msg Rx Ind</code>, offener Kreis) und sendet seine eigene Botschaft mit nachfolgender Sendebestätigung (<code>NM-Msg Tx Conf</code>, geschlossener Kreis).\n</li><li>Sowohl der Empfang (<code>Rx Ind</code>) als auch das erfolgreiche Senden (<code>Tx Conf</code>) führen auf dem jeweiligen Knoten zum Neustart des NM-Timeout-Timers (<code>Restart of the NM-Timeout Timer</code>), sodass dieser nicht abläuft, solange zyklisch NM-Botschaften ausgetauscht werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Verständnis der Interaktion zwischen Busload-Reduction-Mechanismen und dem Standard-NM-Timing in <code>CanNm</code>. Software-Entwickler müssen sicherstellen, dass bei Aufruf von <code>Nm_StartTransmission()</code> die Botschaftsübertragung im CanNm ordnungsgemäß initiiert wird und der NM-Timeout-Timer (<code>NM-Timeout Timer</code>) sowohl bei eingehenden NM-Nachrichten (<code>CanNm_RxIndication</code>) als auch bei eigenen Sendebestätigungen (<code>CanNm_TxConfirmation</code>) verlässlich neu gestartet wird, um einen fehlerhaften Timeout-Übergang in den <code>Ready Sleep State</code> oder Netzwerk-Shutdown zu verhindern.</p>"}, {"id": "FIG-29544542316568d9", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Botschaftssequenzdiagramm (Timing Diagram) im Kontext des AUTOSAR Classic CAN Network Managements (<code>CanNm</code>). Das Diagramm illustriert das Verhalten von drei Netzwerkknoten (Knoten 1, 2, 3) bei Beendigung der Buslastreduktion und Reaktivierung der regulären NM-Botschaftsübertragung sowie das Zurücksetzen des NM-Timeout-Timers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Netzwerkknoten</strong>: Knoten 1 (grün), Knoten 2 (blau) und Knoten 3 (gelb), jeweils auf separaten horizontalen Zeitachsen dargestellt.\n</li><li><strong>Zustände / Modi</strong>:\n<ul class=\"fig-list\"><li><code>RM</code>: Repeat Message State\n</li><li><code>NO</code>: Normal Operation State\n</li><li><code>RS</code>: Ready Sleep State\n</li></ul>\n</li><li><strong>Schnittstellen / API-Aufrufe</strong>:\n<ul class=\"fig-list\"><li><code>Nm_StopBusLoadReduction()</code>\n</li><li><code>Nm_StartTransmission()</code>\n</li></ul>\n</li><li><strong>Ereignisse &amp; Timer-Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>Restart of the NM-Timeout Timer</code>\n</li><li>Auslöser <code>at NM-Msg Tx Conf</code>: Bestätigung einer gesendeten NM-PDU (gefüllter Kreis)\n</li><li>Auslöser <code>at NM-Msg Rx Ind</code>: Empfangsanzeige einer NM-PDU (ungefüllter Kreis)\n</li><li>NM-Sendeimpulse/Botschaften der Knoten auf dem Bus (farbige vertikale Balken 1, 2, 3) entlang der Zeitachse <code>time</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initial befinden sich alle drei Knoten im Zustand <code>RM</code> (Repeat Message).\n</li><li>Zu einem definierten Zeitpunkt wird für alle Knoten <code>(1,2,3)</code> der synchrone Ablauf getriggert: <code>Nm_StopBusLoadReduction()</code> gefolgt von <code>Nm_StartTransmission()</code>.\n</li><li>In der Folge senden die Knoten nacheinander zyklisch ihre NM-Botschaften (dargestellt durch die farbigen Balken 1, 2, 3 auf dem Bus).\n</li><li>Jeder Knoten empfängt die Botschaften der jeweils anderen Knoten (<code>NM-Msg Rx Ind</code>, offener Kreis) und sendet seine eigene Botschaft mit nachfolgender Sendebestätigung (<code>NM-Msg Tx Conf</code>, geschlossener Kreis).\n</li><li>Sowohl der Empfang (<code>Rx Ind</code>) als auch das erfolgreiche Senden (<code>Tx Conf</code>) führen auf dem jeweiligen Knoten zum Neustart des NM-Timeout-Timers (<code>Restart of the NM-Timeout Timer</code>), sodass dieser nicht abläuft, solange zyklisch NM-Botschaften ausgetauscht werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Verständnis der Interaktion zwischen Busload-Reduction-Mechanismen und dem Standard-NM-Timing in <code>CanNm</code>. Software-Entwickler müssen sicherstellen, dass bei Aufruf von <code>Nm_StartTransmission()</code> die Botschaftsübertragung im CanNm ordnungsgemäß initiiert wird und der NM-Timeout-Timer (<code>NM-Timeout Timer</code>) sowohl bei eingehenden NM-Nachrichten (<code>CanNm_RxIndication</code>) als auch bei eigenen Sendebestätigungen (<code>CanNm_TxConfirmation</code>) verlässlich neu gestartet wird, um einen fehlerhaften Timeout-Übergang in den <code>Ready Sleep State</code> oder Netzwerk-Shutdown zu verhindern.</p>"}], "trans": [{"from": "FIG-f303b83119d1a616", "to": "FIG-29544542316568d9", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildqualität und Rendering: Schärfere Vektordarstellung bzw. Schriftenglättung über das gesamte Diagramm (bessere Lesbarkeit von Texten wie Legende und Funktionsaufrufen).\n</li><li>Rahmenkonturen: Textfelder für den Zustandsbezeichner „RM“ (Repeat Message) bei Knoten 1, 2 und 3 sowie für den Funktionsaufrufblock unten links („(1,2,3): Nm_StopBusLoadReduction(); Nm_StartTransmission();“) sind mit dünnen grauen Begrenzungsrahmen versehen.\n</li></ul>"}]};
